def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    out = g.copy()
    # Stage 1: interior rows that are entirely open (0) from wall to wall
    for y in range(1, H - 1):
        if np.all(g[y, 1:W - 1] == 0):
            out[y, 1:W - 1] = 3
    emit(out, "Fill with 3 every interior row that is completely open (all 0) between the left and right walls.")
    # Stage 2: interior columns that are entirely open from top wall to bottom wall
    for x in range(1, W - 1):
        if np.all(g[1:H - 1, x] == 0):
            out[1:H - 1, x] = 3
    emit(out, "Fill with 3 every interior column that is completely open (all 0) between the top and bottom walls.")
    return out
